\draw (Y)--(Z) node[midway,below right] {$4.5$ km};
\draw (X)--(Z) node[midway,above] {$\approx 6.1$ km};
\pic[draw,"$70^{\circ}$",angle radius=0.5cm,angle eccentricity=1.6] {angle=Z--Y--X};
